    char first[16] = "";
    char second[16] = "";
    int left = 0;
    int right = 0;
    int rows = parse("name,qty,price\nbolt,12,1\nnut,40,2\nwasher,0,3", first, second, &left, &right);
    printf("columns %s,%s\n", first, second);
    printf("%s: %d\n", first, left);
    printf("%s: %d\n", second, right);
    printf("rows %d\n", rows);
    return 0;
}

