    for (int i = 0; i < count; i++) {
        capitalise(words[i]);
    }
    for (int i = 0; i < count; i++) {
        if (i > 0) {
            printf(" | ");
        }
        printf("%s", words[i]);
    }
    printf("\n%d %s %d\n", count, words[longest(words, count)],
           total_letters(words, count));
    return 0;
}

