        if (name == "push") {
            int value = std::stoi(op.substr(space + 1));
            stack.push(value);
            out.push_back("push " + std::to_string(value));
        } else {
            int value = 0;
            bool ok = name == "pop" ? stack.pop(value) : stack.peek(value);
            out.push_back(name + (ok ? " " + std::to_string(value) : " none"));
        }
    }
    return out;
}

