class Account {
  constructor(opening) {
    this.balance = opening;
    this.log = [];
  }

  deposit(amount) {
    this.balance += amount;
    this.log.push(["deposit", amount, this.balance]);
  }

  withdraw(amount) {
    if (amount > this.balance) {
      this.log.push(["refused", amount, this.balance]);
      return false;
    }
    this.balance -= amount;
    this.log.push(["withdraw", amount, this.balance]);
    return true;
  }
}

