TEXT = 'the quick brown fox jumps over the lazy dog the fox'

def tokens(text):
    return text.split()

def counts(words):
    table = {}
    for word in words:
        table[word] = table.get(word, 0) + 1
    return table

def ranked(table):
    return sorted(table.items(), key=lambda pair: (-pair[1], pair[0]))

def report(rows):
    return '\n'.join(f'{word}: {count}' for word, count in rows[:4])

print(report(ranked(counts(tokens(TEXT)))))

