class Stack:
    def __init__(self):
        self.items = []

    def push(self, value):
        self.items.append(value)

    def pop(self):
        return self.items.pop() if self.items else None

    def peek(self):
        return self.items[-1] if self.items else None

def run(stack, ops):
    out = []
    for op in ops:
        name, _, arg = op.partition(' ')
        if name == 'push':
            stack.push(int(arg))
            out.append(f'push {arg}')
        elif name == 'pop':
            out.append(f'pop {stack.pop()}')
        else:
            out.append(f'peek {stack.peek()}')
    return out

OPS = [
    'push 3',
    'push 1',
    'peek',
    'pop',
    'push 4',
    'pop',
    'pop',
]
print('\n'.join(run(Stack(), OPS)))

