DATA = 'name,qty,price\nbolt,12,0.50\nnut,40,0.10\nwasher,0,0.05'

def parse(data):
    lines = [line for line in data.strip().splitlines() if line]
    header = lines[0].split(',')
    rows = [line.split(',') for line in lines[1:]]
    return header, rows

def totals(header, rows):
    out = {}
    for index, name in enumerate(header[1:], start=1):
        try:
            out[name] = sum(float(row[index]) for row in rows)
        except ValueError:
            out[name] = float(len(rows))
    return out

header, rows = parse(DATA)
print('columns', ','.join(header[1:]))
for name, value in totals(header, rows).items():
    print(f'{name}: {value:.2f}')

