NUMBERS = [6, 11, 12, 7, 11, 13, 17, 19]

def factorise(value):
    out = []
    divisor = 2
    while divisor * divisor <= value:
        while value % divisor == 0:
            out.append(divisor)
            value //= divisor
        divisor += 1
    if value > 1:
        out.append(value)
    return out

def table(numbers):
    return [(n, factorise(n)) for n in numbers]

for number, parts in table(NUMBERS):
    print(f'{number}: ' + ' x '.join(str(part) for part in parts))

