class Account:
    def __init__(self, opening):
        self.balance = opening
        self.log = []

    def deposit(self, amount):
        self.balance += amount
        self.log.append(('deposit', amount, self.balance))

    def withdraw(self, amount):
        if amount > self.balance:
            self.log.append(('refused', amount, self.balance))
            return False
        self.balance -= amount
        self.log.append(('withdraw', amount, self.balance))
        return True

OPS = [('open', 100), ('deposit', 50), ('withdraw', 30), ('withdraw', 500)]

account = Account(OPS[0][1])
account.log.append(('open', OPS[0][1], OPS[0][1]))
for kind, amount in OPS[1:]:
    account.deposit(amount) if kind == 'deposit' else account.withdraw(amount)

for kind, amount, balance in account.log:
    print(f'{kind:<9} {amount:>4} -> {balance:>4}')

