    }
    if value > 1 {
        out.push(value);
    }
    out
}

fn render(parts: &[i32]) -> String {
    parts
        .iter()
        .map(|part| part.to_string())
        .collect::<Vec<String>>()
        .join(" x ")
}

fn main() {
    let numbers: Vec<i32> = vec![48, 96, 97, 7, 11, 13, 17, 19];
    for number in numbers {
        println!("{}: {}", number, render(&factorise(number)));
    }
}

fn factorise(mut value: i32) -> Vec<i32> {
    let mut out = Vec::new();
    let mut divisor = 2;
    while divisor * divisor <= value {
        while value % divisor == 0 {
            out.push(divisor);
            value /= divisor;
        }
        divisor += 1;
    }
    if value > 1 {
        out.push(value);
    }
    out
}

fn render(parts: &[i32]) -> String {
    parts
        .iter()
        .map(|part| part.to_string())
        .collect::<Vec<String>>()
        .join(" x ")
}

fn main() {
    let numbers: Vec<i32> = vec![60, 119, 120, 7, 11, 13, 17, 19];
    for number in numbers {
        println!("{}: {}", number, render(&factorise(number)));
    }
}

struct Entry {
    kind: String,
    amount: i32,
    balance: i32,
}

struct Account {
    balance: i32,
    log: Vec<Entry>,
}

impl Account {
    fn open(amount: i32) -> Account {
        Account {
            balance: amount,
            log: vec![Entry { kind: "open".to_string(), amount, balance: amount }],
        }
    }

    fn deposit(&mut self, amount: i32) {
        self.balance += amount;
        self.log.push(Entry {
            kind: "deposit".to_string(),
            amount,
            balance: self.balance,
        });
    }

    fn withdraw(&mut self, amount: i32) {
        if amount > self.balance {
            self.log.push(Entry {
                kind: "refused".to_string(),
                amount,
                balance: self.balance,
            });
            return;
        }
        self.balance -= amount;
        self.log.push(Entry {
            kind: "withdraw".to_string(),
            amount,
            balance: self.balance,
        });
    }
}

