final class Account {
    var balance: Int
    var log: [(String, Int, Int)] = []

    init(_ opening: Int) {
        self.balance = opening
    }

    func deposit(_ amount: Int) {
        balance += amount
        log.append(("deposit", amount, balance))
    }

    func withdraw(_ amount: Int) {
        if amount > balance {
            log.append(("refused", amount, balance))
